import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs } from "../_utils/component.helper";

const CHEVRON_LEFT_SVG =
  '<svg viewBox="0 0 16 16" width="12" height="12" fill="none" aria-hidden="true" focusable="false"><path d="M10 4 6 8l4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';

const ROOT_ID_PARAM_NAME = "rootId";

/**
 * This tenant's real Matrix domain -- confirmed live via `dxp-inspector`:
 * an Asset-Tree-picked matrix-asset-uri resolved successfully as
 * `matrix-asset://dxp-ntgov-web/1628941`. `info.ctx` never exposes a
 * domain (only a bare `assetId` -- confirmed exhaustively via
 * `dxp-inspector`'s own shape-inspection utility earlier this session), so
 * this is hardcoded rather than guessed. See side-navigation.spec.md
 * assumption 7.
 */
const MATRIX_DOMAIN = "dxp-ntgov-web";

/**
 * `sidebar_items` is a multi-value metadata field (e.g. ["sidebar_nav",
 * "anchor_nav"]) editors use to opt individual pages into different
 * page-furniture pieces. This component only ever renders when the current
 * page has opted into this exact value -- pages that only want e.g.
 * "anchor_nav" get nothing at all, not an empty shell. See
 * side-navigation.spec.md assumption 8.
 */
const SIDEBAR_NAV_FLAG = "sidebar_nav";

export default {
  async main(input = {}, info = {}) {
    const attrs = componentAttrs("side-navigation", input);
    const contentApiUrl = info?.env?.CONTENT_API_URL;
    const fns = info?.fns;

    const current = await resolveAsset(buildUri(info?.ctx?.assetId), fns);
    const currentMetadata = current?.metadata || {};

    if (
      !metadataValues(currentMetadata, "sidebar_items").includes(
        SIDEBAR_NAV_FLAG,
      )
    ) {
      return "";
    }

    const parentId = firstMetadataValue(currentMetadata, "sidebar_parent");
    const currentAssetId =
      firstMetadataValue(currentMetadata, "sidebar_current_asset") ||
      info?.ctx?.assetId ||
      "";

    const [parentAsset, siblings, currentPageChildren] = await Promise.all([
      resolveAsset(buildUri(parentId), fns),
      fetchChildren(parentId, contentApiUrl),
      fetchChildren(currentAssetId, contentApiUrl),
    ]);

    const items = siblings
      .map((child) => toNavItem(child, currentAssetId, currentPageChildren))
      .filter(Boolean);

    const parent = parentAsset?.url
      ? {
          name: parentAsset.name || parentAsset.short_name || "",
          url: parentAsset.url,
        }
      : null;

    return renderSideNavigation(parent, items, attrs);
  },
};

function buildUri(id) {
  return id ? `matrix-asset://${MATRIX_DOMAIN}/${id}` : "";
}

/**
 * fns.resolveUri wraps its result in a { ok, data } envelope -- confirmed
 * against a live Squiz DXP backend (see card.spec.md assumption 4, the same
 * mechanism reused here). Checking for the `data` key's presence, not just
 * truthiness, avoids misreading a legitimate `{ data: null }` "not found"
 * envelope as the raw asset itself.
 */
async function resolveAsset(uri, fns) {
  if (!uri || typeof fns?.resolveUri !== "function") return null;
  try {
    const result = await fns.resolveUri(uri);
    return unwrapResolved(result);
  } catch {
    return null;
  }
}

function unwrapResolved(result) {
  if (!result || typeof result !== "object") return null;
  if ("data" in result) return result.data ?? null;
  return result;
}

/**
 * Per the real Matrix asset schema (confirmed live via dxp-inspector for
 * this exact component), `metadata` is a key-value map where every value is
 * an array of strings -- this reads the first value for a given key. Same
 * helper as `card`/`document`.
 */
function firstMetadataValue(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? value[0] || "" : "";
}

/**
 * Same metadata shape as firstMetadataValue(), but returns the whole
 * multi-value array instead of just the first entry -- for fields like
 * `sidebar_items` where membership (not just "the first value") is what
 * matters.
 */
function metadataValues(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? value : [];
}

/**
 * Fetches an asset's children (by raw ID) via a plain unauthenticated
 * fetch() against CONTENT_API_URL -- not info.fns, which has no
 * children-listing capability at all on this tenant. Called twice from
 * main(): once for `parentId` (-> the sibling list) and once for
 * `currentAssetId` (-> the current page's own sub-pages, nested under it --
 * see assumption 4). Each returned item's own `id`/`name`/`url` is used
 * directly (unlike this component's own current-asset resolution, which
 * needs full metadata and therefore goes through fns.resolveUri() instead).
 * See side-navigation.spec.md assumption 1.
 */
async function fetchChildren(assetId, contentApiUrl) {
  if (!assetId || !contentApiUrl) return [];

  const url = `${contentApiUrl}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(assetId)}`;

  try {
    const res = await fetch(url);
    if (!res.ok) return [];
    const body = await res.json();
    return Array.isArray(body) ? body : [];
  } catch {
    return [];
  }
}

/**
 * Maps one child from the Content API feed onto a render-ready nav item.
 * `current` is a strict string-compared ID match against `currentAssetId`
 * (sourced from the current page's own `sidebar_current_asset` metadata,
 * not `info.ctx.assetId` directly -- see assumption 7) -- both are real
 * Matrix asset IDs, so this is an exact match, not a fuzzy URL/label
 * comparison. See side-navigation.spec.md assumption 2. When this item *is*
 * the current page, its own children (already fetched in main()) are
 * attached and rendered nested beneath it -- see assumption 4. Non-current
 * items never get nested children: only the active page's own sub-pages are
 * shown, not every sibling's.
 */
function toNavItem(child, currentAssetId, currentPageChildren) {
  if (!child || !child.url) return null;
  const current =
    Boolean(currentAssetId) && String(child.id) === String(currentAssetId);
  return {
    label: child.name || "",
    href: child.url,
    current,
    children: current
      ? currentPageChildren.map(toChildLink).filter(Boolean)
      : [],
  };
}

function toChildLink(child) {
  if (!child || !child.url) return null;
  return { label: child.name || "", href: child.url };
}

function renderSideNavigation(parent, items, attrs) {
  const backHtml = parent
    ? /*html*/ `
    <a class="side-navigation__back" href="${escURL(parent.url)}">
      ${CHEVRON_LEFT_SVG}
      <span>${escHTML(parent.name)}</span>
    </a>`
    : "";

  const itemsHtml = items
    .map((item) => {
      const contentHtml = item.current
        ? `<span class="side-navigation__link side-navigation__link--current" aria-current="page">${escHTML(item.label)}</span>`
        : `<a class="side-navigation__link" href="${escURL(item.href)}">${escHTML(item.label)}</a>`;

      const nestedHtml = item.children.length
        ? `<ol class="side-navigation__sublist">${item.children
            .map(
              (child) =>
                `<li class="side-navigation__subitem"><a class="side-navigation__link side-navigation__link--sub" href="${escURL(child.href)}">${escHTML(child.label)}</a></li>`,
            )
            .join("")}</ol>`
        : "";

      return `<li class="side-navigation__item${item.current ? " side-navigation__item--current" : ""}">${contentHtml}${nestedHtml}</li>`;
    })
    .join("");

  return /*html*/ `
<nav ${attrs} class="side-navigation" aria-label="Section navigation">
  ${backHtml}
  <ol class="side-navigation__list">
    ${itemsHtml}
  </ol>
</nav>
`;
}
